export function mergePhase3Content(content) {
    content.storyline.scenes = {
        ...content.storyline.scenes,
        ...PHASE3_SCENES,
    };
    if (!content.randomEvents)
        content.randomEvents = [];
    content.randomEvents = [...content.randomEvents, ...PHASE3_EVENTS];
    return content;
}
